#pragma once

// Every model request an Agent posts, written to a directory exactly as
// posted, for checking what a provider was sent and what it cached. Tests and
// the shell harness only; the app does not ship it. GUI-free.
//
// For the n-th request of a run (n from 1, four digits, in post order):
//   NNNN-request.json       the body, byte for byte as the transport got it
//   NNNN-request.meta.json  provider, URL, header names (credentials
//                           redacted), chat id, purpose, request id, attempt,
//                           time and body length
//   NNNN-response.sse       the response stream as it was received
//   NNNN-response.json      HTTP status, usage, stop reason, assembled text
//                           and any error, read from that stream
// The response files are written when the stream ends, fails, is cancelled or
// is replaced by the next request. tests/project_prompt/prefix_check.py reads
// the directory.

#include "slic3r/GUI/JusPrin/Agent/AgentService.hpp"
#include "slic3r/GUI/JusPrin/Agent/AgentTransport.hpp"

#include <nlohmann/json.hpp>

#include <algorithm>
#include <cctype>
#include <chrono>
#include <cstdio>
#include <ctime>
#include <filesystem>
#include <fstream>
#include <functional>
#include <memory>
#include <mutex>
#include <string>
#include <utility>

namespace Slic3r::GUI::JusPrin::Agent {

class RequestLog
{
public:
    // `directory` is created if missing and must hold nothing, so a run's
    // numbering never mixes with an earlier run's. `chat_id` names the chat a
    // request belongs to, read at each post.
    RequestLog(std::filesystem::path directory, std::function<std::string()> chat_id)
        : m_state(std::make_shared<State>())
    {
        std::filesystem::create_directories(directory);
        if (!std::filesystem::is_empty(directory))
            throw std::runtime_error("the request log directory is not empty: " + directory.string());
        m_state->directory = std::move(directory);
        m_state->chat_id   = std::move(chat_id);
    }

    // `inner`, with every request it is given logged first. `provider` is the
    // ProviderProfile id whose wire format the bodies are in.
    std::unique_ptr<IAgentHttpTransport> transport(std::string provider, std::unique_ptr<IAgentHttpTransport> inner) const
    {
        return std::make_unique<Transport>(m_state, std::move(provider), std::move(inner));
    }

    // `inner`, telling the log the purpose, request id and attempt of the
    // turn each later request belongs to. Its transport must be one of this
    // log's.
    AgentServicePtr agent(AgentServicePtr inner) const { return std::make_unique<Service>(m_state, std::move(inner)); }

private:
    struct State
    {
        std::filesystem::path        directory;
        std::function<std::string()> chat_id;
        int                          posted{0};
        // The turn the next request belongs to.
        std::string purpose{"unknown"};
        std::string request_id;
        int         attempt{0};
    };

    // One request's response, written once by whichever comes first: the
    // stream's end, its failure, or its cancellation.
    struct Pending
    {
        std::mutex            mutex;
        std::filesystem::path stem;
        std::string           stream;
        unsigned              status{0};
        bool                  written{false};

        void finish(const std::string& outcome, const std::string& error = {})
        {
            std::lock_guard<std::mutex> guard(mutex);
            if (written)
                return;
            written = true;
            write(stem.string() + "-response.sse", stream);
            nlohmann::ordered_json record = read_stream(stream);
            record["outcome"] = outcome;
            record["status"]  = status;
            if (!error.empty())
                record["transport_error"] = error;
            record["finished_at"] = now();
            write(stem.string() + "-response.json", record.dump(2) + "\n");
        }
    };

    class Transport final : public IAgentHttpTransport
    {
    public:
        Transport(std::shared_ptr<State> state, std::string provider, std::unique_ptr<IAgentHttpTransport> inner)
            : m_state(std::move(state)), m_provider(std::move(provider)), m_inner(std::move(inner))
        {}

        bool post(AgentHttpRequest request, EventFn event) override
        {
            char number[16];
            std::snprintf(number, sizeof number, "%04d", ++m_state->posted);
            auto pending  = std::make_shared<Pending>();
            pending->stem = m_state->directory / number;
            write(pending->stem.string() + "-request.json", request.body);
            nlohmann::ordered_json headers = nlohmann::ordered_json::object();
            for (const AgentHttpHeader& header : request.headers)
                headers[header.name] = secret_header(header.name) ? "<redacted>" : header.value;
            const nlohmann::ordered_json meta{{"index", m_state->posted},
                                              {"provider", m_provider},
                                              {"url", request.url},
                                              {"headers", headers},
                                              {"chat_id", m_state->chat_id ? m_state->chat_id() : std::string()},
                                              {"purpose", m_state->purpose},
                                              {"request_id", m_state->request_id},
                                              {"attempt", m_state->attempt},
                                              {"posted_at", now()},
                                              {"body_bytes", request.body.size()}};
            write(pending->stem.string() + "-request.meta.json", meta.dump(2) + "\n");

            // A transport serves one request at a time, so posting cancels
            // the one before.
            const std::shared_ptr<Pending> previous = std::exchange(m_pending, pending);
            const bool started = m_inner->post(std::move(request), [pending, event = std::move(event)](AgentHttpEvent http) {
                {
                    std::lock_guard<std::mutex> guard(pending->mutex);
                    if (http.kind == AgentHttpEvent::Kind::Data)
                        pending->stream += http.data;
                    if (http.status != 0)
                        pending->status = http.status;
                }
                if (http.kind == AgentHttpEvent::Kind::Complete)
                    pending->finish("complete");
                else if (http.kind == AgentHttpEvent::Kind::Error)
                    pending->finish("error", http.error);
                event(std::move(http));
            });
            if (previous)
                previous->finish("replaced");
            if (!started)
                pending->finish("not_started");
            return started;
        }

        void cancel() override
        {
            m_inner->cancel();
            if (m_pending)
                m_pending->finish("cancelled");
        }

    private:
        std::shared_ptr<State>               m_state;
        std::string                          m_provider;
        std::unique_ptr<IAgentHttpTransport> m_inner;
        std::shared_ptr<Pending>             m_pending;
    };

    class Service final : public IAgentService
    {
    public:
        Service(std::shared_ptr<State> state, AgentServicePtr inner) : m_state(std::move(state)), m_inner(std::move(inner)) {}

        bool ready() const override { return m_inner->ready(); }
        bool busy() const override { return m_inner->busy(); }
        bool start(const AgentRequest& request) override
        {
            m_state->purpose    = request.purpose == AgentRequest::Purpose::ConversationTitle ? "title" : "reply";
            m_state->request_id = request.request_id;
            m_state->attempt    = request.attempt;
            return m_inner->start(request);
        }
        bool continue_after_tool(const AgentToolResult& result) override { return m_inner->continue_after_tool(result); }
        void cancel() override { m_inner->cancel(); }
        std::optional<AgentEvent> poll() override { return m_inner->poll(); }

    private:
        std::shared_ptr<State> m_state;
        AgentServicePtr        m_inner;
    };

    static void write(const std::string& path, const std::string& bytes)
    {
        std::ofstream file(path, std::ios::binary);
        file.write(bytes.data(), static_cast<std::streamsize>(bytes.size()));
        if (!file)
            throw std::runtime_error("could not write " + path);
    }

    static bool secret_header(std::string name)
    {
        std::transform(name.begin(), name.end(), name.begin(), [](unsigned char c) { return char(std::tolower(c)); });
        for (const char* word : {"authorization", "key", "token", "cookie", "secret"})
            if (name.find(word) != std::string::npos)
                return true;
        return false;
    }

    static std::string now()
    {
        const auto        time   = std::chrono::system_clock::now();
        const std::time_t whole  = std::chrono::system_clock::to_time_t(time);
        const auto        millis = std::chrono::duration_cast<std::chrono::milliseconds>(time.time_since_epoch()).count() % 1000;
        std::tm           utc{};
#ifdef _WIN32
        gmtime_s(&utc, &whole);
#else
        gmtime_r(&whole, &utc);
#endif
        char text[32];
        std::snprintf(text, sizeof text, "%04d-%02d-%02dT%02d:%02d:%02d.%03dZ", utc.tm_year + 1900, utc.tm_mon + 1, utc.tm_mday,
                      utc.tm_hour, utc.tm_min, utc.tm_sec, int(millis));
        return text;
    }

    // The usage, stop reason, text and error a Messages API or Responses API
    // stream carries. Usage fields are kept as the provider named them.
    static nlohmann::ordered_json read_stream(const std::string& stream)
    {
        nlohmann::ordered_json record{{"usage", nlohmann::ordered_json::object()}, {"stop", nullptr}, {"text", ""}};
        std::string            text;
        std::size_t            begin = 0;
        while (begin < stream.size()) {
            std::size_t end = stream.find('\n', begin);
            if (end == std::string::npos)
                end = stream.size();
            std::string line = stream.substr(begin, end - begin);
            begin            = end + 1;
            if (!line.empty() && line.back() == '\r')
                line.pop_back();
            if (line.rfind("data:", 0) != 0)
                continue;
            const nlohmann::json event = nlohmann::json::parse(line.substr(5), nullptr, false);
            if (!event.is_object())
                continue;
            const std::string type = event.value("type", "");
            const auto        merge_usage = [&record](const nlohmann::json& usage) {
                if (usage.is_object())
                    for (const auto& [name, value] : usage.items())
                        record["usage"][name] = value;
            };
            if (type == "message_start" && event.contains("message")) { // Messages API
                merge_usage(event["message"].value("usage", nlohmann::json()));
                record["model"] = event["message"].value("model", "");
            } else if (type == "message_delta") {
                merge_usage(event.value("usage", nlohmann::json()));
                if (event.contains("delta") && event["delta"].contains("stop_reason"))
                    record["stop"] = event["delta"]["stop_reason"];
            } else if (type == "content_block_delta" && event.contains("delta") &&
                       event["delta"].value("type", "") == "text_delta") {
                text += event["delta"].value("text", "");
            } else if (type == "response.output_text.delta") { // Responses API
                text += event.value("delta", "");
            } else if ((type == "response.completed" || type == "response.incomplete" || type == "response.failed") &&
                       event.contains("response")) {
                const nlohmann::json& response = event["response"];
                merge_usage(response.value("usage", nlohmann::json()));
                record["stop"] = response.value("status", type.substr(9));
                if (response.contains("incomplete_details") && !response["incomplete_details"].is_null())
                    record["incomplete_details"] = response["incomplete_details"];
                if (response.contains("error") && !response["error"].is_null())
                    record["error"] = response["error"];
                if (response.contains("model"))
                    record["model"] = response["model"];
            } else if (type == "error") {
                record["error"] = event.contains("error") ? event["error"] : event;
            }
        }
        record["text"] = text;
        return record;
    }

    std::shared_ptr<State> m_state;
};

