    return std::string((std::istreambuf_iterator<char>(file)), std::istreambuf_iterator<char>());
}

// Two turns of one chat through the request log, against a provider that
// keeps each reply request's body as it was posted.
void the_log_keeps_every_request(const WireFormat& wire)
{
    const JusPrinTest::McpDirectory directory;
    const std::filesystem::path     logged = directory.root / "requests";
    Harness*                        chat   = nullptr;
    RequestLog log(logged, [&chat] { return chat->persistence.document().active_conversation_id(); });
    auto       owner    = std::make_unique<RecordingProvider>(wire);
    RecordingProvider* provider = owner.get();
    Harness harness(log.agent(make_provider_agent(*profile_for(wire.provider), "key-that-must-not-be-logged", "", "",
                                                  log.transport(wire.provider, std::move(owner)))));
    chat = &harness;
    harness.handshake();
    const auto turn = [&](const std::string& text, const std::string& reply) {
        provider->script.push_back({reply});
        harness.send_user_message(text, "c-log-" + std::to_string(provider->replies.size()));
        for (int i = 0; i < 10; ++i) {
            harness.pump_all();
            pump_tools_to_completion(harness);
        }
        REQUIRE(provider->script.empty());
    };
    turn("What is on the plate?", "Two cubes.");
    turn("And how long will it take?", "About an hour.");
    REQUIRE(provider->replies.size() == 2);

    std::vector<std::filesystem::path> requests;
    for (const auto& entry : std::filesystem::directory_iterator(logged))
        if (entry.path().filename().string().size() == std::string("0001-request.json").size() &&
            entry.path().filename().string().substr(4) == "-request.json")
            requests.push_back(entry.path());
    std::sort(requests.begin(), requests.end());
    // The two replies and, after the first, the chat's title.
    REQUIRE(requests.size() == 3);

    const std::vector<std::string> answers{"Two cubes.", "About an hour."};
    std::size_t                    replies = 0;
    std::string                    chat_id;
    for (std::size_t n = 0; n < requests.size(); ++n) {
        const std::string stem = requests[n].string().substr(0, requests[n].string().size() - std::string("-request.json").size());
        INFO("request " << n + 1);
        CHECK(requests[n].filename().string().substr(0, 4) == (n == 0 ? "0001" : n == 1 ? "0002" : "0003"));
        const std::string meta_text = file_bytes(stem + "-request.meta.json");
        CHECK(meta_text.find("key-that-must-not-be-logged") == std::string::npos);
        const json meta     = json::parse(meta_text);
        const json response = json::parse(file_bytes(stem + "-response.json"));
        CHECK(meta["provider"] == wire.provider);
        CHECK(meta["index"] == n + 1);
        CHECK(meta["body_bytes"] == file_bytes(requests[n]).size());
        CHECK(response["outcome"] == "complete");
        CHECK(response["status"] == 200);
        CHECK(response["usage"]["input_tokens"] == 100);
        CHECK(response["usage"]["output_tokens"] == 10);
        CHECK(response["stop"] == (wire.provider == "anthropic" ? "end_turn" : "completed"));
        CHECK_FALSE(file_bytes(stem + "-response.sse").empty());
        if (meta["purpose"] == "title") {
            CHECK(response["text"] == "A title");
            continue;
        }
        REQUIRE(meta["purpose"] == "reply");
        REQUIRE(replies < provider->replies.size());
        // Byte for byte what the provider was posted.
        CHECK(file_bytes(requests[n]) == provider->replies[replies]);
        CHECK(response["text"] == answers[replies]);
        CHECK_FALSE(meta["chat_id"].get<std::string>().empty());
        if (replies == 0)
            chat_id = meta["chat_id"];
        CHECK(meta["chat_id"] == chat_id);
        ++replies;
    }
    CHECK(replies == 2);
    // A run's numbering never continues an earlier run's.
    CHECK_THROWS_AS(RequestLog(logged, {}), std::runtime_error);
}

} // namespace

TEST_CASE("the request log writes each request as posted, with its response's usage", "[agent][request-log]")
{
    SECTION("Anthropic Messages") { the_log_keeps_every_request(anthropic_wire()); }
    SECTION("OpenAI Responses") { the_log_keeps_every_request(responses_wire()); }
}
