#!/usr/bin/env python3
"""How much of each request the one before it shares, byte for byte.

Reads a request log the shell harness wrote with --request-log (see
tests/jusprin_support/RequestLog.hpp): NNNN-request.json, the body as posted,
and NNNN-request.meta.json beside it. For each pair of consecutive requests
of the same chat and purpose it reports the length of their common byte
prefix, the first byte at which they differ, and the JSON path that byte
belongs to in each body. A provider caches a prompt prefix, so a difference
inside an earlier message is a cache leak; "append" means the earlier body
ended an array where the later one goes on with it, which is what a growing
chat should look like.

--ignore-key KEY drops every object member named KEY from both bodies first
(for example cache_control, whose breakpoint moves to the newest user
content on every Anthropic request without changing what is cached). The
bodies are then compared as Python writes them back, not as posted, and the
report says so.

Usage: python3 tests/project_prompt/prefix_check.py LOG_DIR [--ignore-key KEY]... [--json]
"""

import argparse
import json
import pathlib
import re
import sys

WHITESPACE = b" \t\r\n"


def common_prefix(a, b):
    """The length of the bytes `a` and `b` open with alike."""
    n = min(len(a), len(b))
    low, high = 0, n
    while low < high:  # halving: bodies are hundreds of kilobytes
        middle = (low + high + 1) // 2
        if a[:middle] == b[:middle]:
            low = middle
        else:
            high = middle - 1
    return low


def _spans(data):
    """Every value in a JSON document as (start, end, path), end exclusive.
    An object member's span starts at its key, so a byte of the key belongs
    to the member."""
    spans = []

    def skip(i):
        while i < len(data) and data[i] in WHITESPACE:
            i += 1
        return i

    def string(i):
        j = i + 1
        while data[j] != 0x22:  # "
            j += 2 if data[j] == 0x5C else 1  # a backslash escapes the next byte
        return j + 1, json.loads(data[i:j + 1])

    def value(i, path):
        i = skip(i)
        start = i
        if data[i] == 0x7B:  # {
            i = skip(i + 1)
            if data[i] == 0x7D:
                i += 1
            else:
                while True:
                    i = skip(i)
                    key_start = i
                    i, key = string(i)
                    i = skip(i) + 1  # the colon
                    i = value(i, path + [key])
                    spans.append((key_start, i, path + [key]))
                    i = skip(i)
                    i += 1
                    if data[i - 1] == 0x7D:
                        break
        elif data[i] == 0x5B:  # [
            i = skip(i + 1)
            if data[i] == 0x5D:
                i += 1
            else:
                index = 0
                while True:
                    i = value(i, path + [index])
                    index += 1
                    i = skip(i) + 1
                    if data[i - 1] == 0x5D:
                        break
        elif data[i] == 0x22:
            i, _ = string(i)
        else:
            while i < len(data) and data[i] not in b",]}" + WHITESPACE:
                i += 1
        spans.append((start, i, path))
        return i

    value(0, [])
    return spans


def path_text(path):
    out = "$"
    for part in path:
        if isinstance(part, int):
            out += "[%d]" % part
        elif re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", part):
            out += "." + part
        else:
            out += "[%s]" % json.dumps(part)
    return out


def path_at(data, offset):
    """The innermost JSON value of `data` that holds byte `offset`, and that
    value's span."""
    best = None
    for start, end, path in _spans(data):
        if start <= offset < end and (best is None or end - start < best[1] - best[0]):
            best = (start, end, path)
    return best


def compare(earlier, later):
    """What `later` shares with `earlier`, as a dict."""
    shared = common_prefix(earlier, later)
    result = {"earlier_bytes": len(earlier), "later_bytes": len(later), "common_prefix": shared}
    if earlier == later:
        result["kind"] = "identical"
        return result
    result["first_difference"] = shared
    held_earlier = path_at(earlier, shared) if shared < len(earlier) else None
    held_later = path_at(later, shared) if shared < len(later) else None
    result["earlier_path"] = path_text(held_earlier[2]) if held_earlier else None
    result["later_path"] = path_text(held_later[2]) if held_later else None
    # The earlier body closes an array here and the later one goes on with it.
    appended = (held_earlier and held_later and held_earlier[2] == held_later[2] and
                earlier[shared:shared + 1] == b"]" and held_earlier[1] == shared + 1 and
                later[shared:shared + 1] == b",")
    result["kind"] = "append" if appended else "changed"
    result["earlier_context"] = earlier[max(0, shared - 40):shared + 40].decode("utf-8", "replace")
    result["later_context"] = later[max(0, shared - 40):shared + 40].decode("utf-8", "replace")
    return result


def without_keys(body, keys):
    def strip(value):
        if isinstance(value, dict):
            return {k: strip(v) for k, v in value.items() if k not in keys}
        if isinstance(value, list):
            return [strip(v) for v in value]
        return value
    return json.dumps(strip(json.loads(body)), ensure_ascii=False, separators=(",", ":")).encode("utf-8")


def read_log(directory):
    """The log's requests in post order, each with its meta."""
    requests = []
    for path in sorted(pathlib.Path(directory).glob("[0-9][0-9][0-9][0-9]-request.json")):
        meta_path = path.with_name(path.name[:4] + "-request.meta.json")
        meta = json.loads(meta_path.read_text("utf-8")) if meta_path.exists() else {}
        requests.append({"name": path.name[:4], "body": path.read_bytes(), "meta": meta})
    return requests


def check(directory, ignore_keys=()):
    """Every consecutive pair of requests of one chat and purpose, compared."""
    groups = {}
    for request in read_log(directory):
        key = (request["meta"].get("chat_id", ""), request["meta"].get("purpose", ""))
        groups.setdefault(key, []).append(request)
    pairs = []
    for (chat, purpose), requests in groups.items():
        for earlier, later in zip(requests, requests[1:]):
            a, b = earlier["body"], later["body"]
            if ignore_keys:
                a, b = without_keys(a, set(ignore_keys)), without_keys(b, set(ignore_keys))
            pairs.append({"chat_id": chat, "purpose": purpose, "earlier": earlier["name"], "later": later["name"],
                          **compare(a, b)})
    return pairs


def describe(pair):
    line = "chat %s %s %s -> %s: shares %d of %d bytes" % (
        pair["chat_id"] or "?", pair["purpose"] or "?", pair["earlier"], pair["later"],
        pair["common_prefix"], pair["earlier_bytes"])
    if pair["kind"] == "identical":
        return line + "; identical"
    line += "; first difference at byte %d, %s" % (pair["first_difference"], pair["earlier_path"])
    if pair["later_path"] != pair["earlier_path"]:
        line += " (later: %s)" % pair["later_path"]
    line += " [%s]" % pair["kind"]
    if pair["kind"] == "changed":
        line += "\n    earlier: %r\n    later:   %r" % (pair["earlier_context"], pair["later_context"])
    return line


def main(argv=None):
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("directory")
    parser.add_argument("--ignore-key", action="append", default=[], metavar="KEY")
    parser.add_argument("--json", action="store_true", help="print the comparisons as JSON")
    options = parser.parse_args(argv)
    pairs = check(options.directory, options.ignore_key)
    if options.json:
        print(json.dumps({"ignored_keys": options.ignore_key, "pairs": pairs}, indent=1, ensure_ascii=False))
        return 0
    if options.ignore_key:
        print("Compared without %s, as rewritten, not as posted." % ", ".join(options.ignore_key))
    for pair in pairs:
        print(describe(pair))
    if not pairs:
        print("No two requests of one chat and purpose in %s." % options.directory)
    return 0


if __name__ == "__main__":
    sys.exit(main())

